import java.time.Duration;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.function.Supplier;

public class ResilientExecutionEngine {

    public <T> CompletableFuture<T> executeWithFaultTolerance(Supplier<T> action, Supplier<T> fallback) {
        return CompletableFuture.supplyAsync(action)
            .orTimeout(200, java.util.concurrent.TimeUnit.MILLISECONDS)
            .exceptionally(ex -> {
                // Log failure metrics, trip circuit breaker if necessary
                System.err.println("Primary operation failed or timed out: " + ex.getMessage());
                return fallback.get();
            });
    }
}
